sysauto_script.script:
(function executeScheduledJob() {
    var emailSubject = "Weekly Event Task Report";
    var emailBody = "<h2>Weekly Event Task Report</h2><br>";

    var eventGR = new GlideRecord('x_1610843_event_0_event_record'); 
    eventGR.query();

    while (eventGR.next()) {
        var eventId = eventGR.getUniqueValue();
        var eventName = eventGR.getValue('event_name');


        var taskUtils = new TaskUtilsScriptInclude();
        var tasks = taskUtils.getTasksForEvent(eventId);


        var taskTable = "<h3>Event: " + eventName + "</h3>";
        taskTable += "<table border='1' cellpadding='5' cellspacing='0'><tr><th>Task Name</th><th>Assigned To</th><th>Due Date</th><th>Status</th></tr>";

        if (Array.isArray(tasks) && tasks.length > 0) {
            tasks.forEach(function(task) {
                taskTable += "<tr><td>" + task.task_name + "</td><td>" + task.assigned_to + "</td><td>" + task.due_date + "</td><td>" + task.status + "</td></tr>";
            });
        } else {
            taskTable += "<tr><td colspan='4'>No tasks found</td></tr>";
        }

        taskTable += "</table><br>";
        emailBody += taskTable;
    }

            gs.eventQueue("x_1610843_event_0.event_task_report",null,null , emailBody);
})();
